package cn.iocoder.yudao.module.zsjos.dal.mysql.personnel;
import cn.iocoder.yudao.framework.mybatis.core.mapper.BaseMapperX; import cn.iocoder.yudao.framework.mybatis.core.query.LambdaQueryWrapperX; import cn.iocoder.yudao.module.zsjos.dal.dataobject.personnel.PartnerStudentLinkDO; import org.apache.ibatis.annotations.Mapper;
@Mapper public interface PartnerStudentLinkMapper extends BaseMapperX<PartnerStudentLinkDO> { default PartnerStudentLinkDO selectActiveByPartner(Long id){return selectOne(new LambdaQueryWrapperX<PartnerStudentLinkDO>().eq(PartnerStudentLinkDO::getPartnerId,id).eq(PartnerStudentLinkDO::getStatus,"active").last("LIMIT 1"));} default PartnerStudentLinkDO selectActiveByStudent(Long id){return selectOne(new LambdaQueryWrapperX<PartnerStudentLinkDO>().eq(PartnerStudentLinkDO::getStudentPersonId,id).eq(PartnerStudentLinkDO::getStatus,"active").last("LIMIT 1"));} }
